def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    strong_bids = []
    low_bids = []

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                b = float(bid)
                prev_bids.append(b)
                if b >= 80:
                    strong_bids.append(b)
                if b <= 40:
                    low_bids.append(b)

    if not alive:
        return min(budget, 18.0)

    tight_supply = supply <= 17
    ample_supply = supply >= 22

    pressure = 0.0
    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
        pressure = max(avg_prev, highest_prev * 0.75)
    else:
        highest_prev = 0.0
        avg_prev = 0.0

    urgent = hp <= 3 or no_water_days >= 2
    semi_urgent = hp <= 5 or no_water_days >= 1

    if urgent:
        if strong_bids:
            bid = min(budget, max(95.0, highest_prev + 4.0))
        else:
            bid = min(budget, max(58.0, pressure + 3.0))
        return float(max(0.0, bid))

    if tight_supply:
        if highest_prev >= 150:
            bid = 34.0 if hp >= 7 else 72.0
        elif highest_prev >= 90:
            bid = 52.0 if hp >= 7 else 78.0
        elif highest_prev >= 35:
            bid = highest_prev + 2.5
        else:
            bid = 33.0
    elif ample_supply:
        if highest_prev >= 150:
            bid = 16.0
        elif highest_prev >= 90:
            bid = 20.0
        elif highest_prev >= 35:
            bid = 24.0
        else:
            bid = 18.0
    else:
        if highest_prev >= 150:
            bid = 20.0 if hp >= 6 else 60.0
        elif highest_prev >= 90:
            bid = 26.0 if hp >= 6 else 54.0
        elif highest_prev >= 35:
            bid = max(28.0, min(48.0, highest_prev + 1.5))
        else:
            bid = 24.0

    if semi_urgent:
        bid = max(bid, 48.0 if not tight_supply else 60.0)

    if day >= 8 and hp >= 6 and budget < 140:
        bid = min(bid, 26.0)

    if ample_supply and len(strong_bids) >= 1 and hp >= 6:
        bid = min(bid, 18.0)

    if len(low_bids) >= 2 and highest_prev <= 40:
        bid = max(bid, 29.0)

    bid = min(budget, bid)
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    # Basic safety/urgency
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Determine how many full water units supply can cover (use int indexing safeguard)
    # This is mainly to scale our bid aggressiveness.
    max_units = int(supply // float(WATER_REQ)) if WATER_REQ > 0 else 0

    alive = [o for o in opponents_status.values() if o.get('alive')]
    if not alive:
        return min(budget, DAILY_SALARY * 0.4)

    # Yesterday bids: immediate reaction only
    prev_bids = []
    for o in alive:
        prev = o.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            prev_bids.append(float(prev['bid']))

    # Estimate opponent pressure from yesterday
    if prev_bids:
        top_bid = max(prev_bids)
        second_bid = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else top_bid
        median_bid = sorted(prev_bids)[len(prev_bids)//2]
    else:
        top_bid = median_bid = second_bid = DAILY_SALARY * 0.5

    # If we are close to losing, bid high; otherwise stay near a competitive but not maximal level.
    # Heuristic: convert no_water_days to urgency.
    # When no_water_days is 0..2 we can be moderate; when >=3 we get aggressive.
    urgency = 0
    if no_water_days >= 3:
        urgency = 2
    elif no_water_days >= 2:
        urgency = 1

    # Also increase urgency if hp is low.
    if hp <= 2:
        urgency = max(urgency, 2)
    elif hp <= 4:
        urgency = max(urgency, 1)

    # Supply scarcity: lower supply implies stronger competition.
    scarcity = 0
    if supply <= (MIN_SUPPLY + 1):
        scarcity = 2
    elif supply <= (MIN_SUPPLY + 5):
        scarcity = 1

    # Decide target bid relative to observed opponent top bids.
    # We try to beat the likely leader only when competition is likely.
    # Use a small increment to reduce tie risk.
    if max_units <= 1:
        # Very scarce: compete near top
        if urgency >= 2 or top_bid >= DAILY_SALARY * 0.85:
            target = min(budget, top_bid + 3.0)
        else:
            target = min(budget, max(median_bid, second_bid + 2.0))
    else:
        # Less scarce: moderate bids unless urgent
        if urgency >= 2:
            target = min(budget, max(top_bid * 0.9, median_bid + 10.0))
        elif urgency >= 1:
            target = min(budget, max(median_bid, second_bid + 5.0))
        else:
            # Conservative: steal water if others overbid; otherwise preserve budget
            # Eric died yesterday, David bid low; so we can undercut slightly below median.
            target = min(budget, max(DAILY_SALARY * 0.45, median_bid * 0.75))

    # Ensure non-negative
    if target < 0:
        target = 0.0

    # Cap by budget
    if target > budget:
        target = budget

    return float(target)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 150
    EPISODE_DAYS = 10
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day_progress_factor = 1 + (day_context['day'] - 1) / (EPISODE_DAYS - 1) * 0.2 if EPISODE_DAYS > 1 else 1.0
    supply_pressure_factor = 1 + (MAX_SUPPLY - day_context['supply']) / (MAX_SUPPLY - MIN_SUPPLY) * 0.1 if (MAX_SUPPLY - MIN_SUPPLY) > 0 else 1.0

    base_competitive_bid = DAILY_SALARY * 0.55 * day_progress_factor * supply_pressure_factor

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    my_bid = base_competitive_bid

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 5:
                my_bid = DAILY_SALARY * 0.3 * day_progress_factor
            else:
                my_bid = DAILY_SALARY * 0.95 * day_progress_factor * supply_pressure_factor
        else:
            my_bid = max(base_competitive_bid, highest_prev_bid + 5.0)

    if my_status['hp'] <= 2:
        my_bid = DAILY_SALARY * 0.98 * day_progress_factor * supply_pressure_factor
    elif my_status['hp'] <= 4:
        my_bid = max(my_bid, DAILY_SALARY * 0.85 * day_progress_factor * supply_pressure_factor)
    elif my_status['hp'] <= 7:
        my_bid = max(my_bid, DAILY_SALARY * 0.7 * day_progress_factor * supply_pressure_factor)

    final_bid = max(1.0, min(my_status['budget'], my_bid))

    return final_bid

